Object.assign(window.TEM8_DICTIONARY, {"goats":{"lemma":"goat","media":{"uk":"media/uk/goat__gb_1.mp3","us":"media/us/goat__us_1.mp3"}},"golden":{"media":{"uk":"media/uk/golden__gb_1.mp3","us":"media/us/golden__us_1.mp3"},"oxford":{"phon":"ˈɡəʊldən","pos":"adjective","senses":[{"en":"made of gold","cn":"金质的；金的","lab":"especially literary","ex":{"en":"a golden crown","cn":"金冕"}},{"en":"bright yellow in colour like gold","cn":"金色的；金黄色的","ex":{"en":"golden hair","cn":"金发"}},{"en":"special; wonderful","cn":"特别的；美好的","ex":{"en":"golden memories","cn":"美好的记忆"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"金色的；金黄色的","en":"Something that is golden is bright yellow in colour.","ex":{"en":"She combed and arranged her golden hair.","cn":"她梳理好自己的金发。"}},{"pos":"ADJ 形容词","cn":"金的；金制的","en":"Golden things are made of gold.","ex":{"en":"...a golden chain with a golden locket.","cn":"带有金制盒式链坠的金项链"}},{"pos":"ADJ 形容词","cn":"极好的；有发展前途的；有益的","en":"If you describe something as golden, you mean it is wonderful because it is likely to be successful and rewarding, or because it is the best of its kind.","ex":{"en":"He says there's a golden opportunity for peace which must be seized.","cn":"他说务必抓住这个谋求和平的绝佳机会。"}},{"pos":"PHRASE 短语","cn":"大受欢迎（或十分成功）的人","en":"If you refer to a man as a golden boy or a woman as a golden girl, you mean that they are especially popular and successful.","ex":{"en":"When the movie came out the critics went wild, hailing Tarantino as the golden boy of the 1990s.","cn":"这部影片上映后，批评家们反响十分热烈，他们将塔拉蒂诺誉为20世纪90年代的金牌男星。"}}]},"examples":[{"en":"He thinks once he gets the money he'll be golden.","cn":"他认为只要拿到钱就万事大吉了。"},{"en":"Businesses have a golden opportunity to expand into new markets.","cn":"商界有开拓新市场的良机。"}]},"goose":{"media":{"uk":"media/uk/goose__gb_1.mp3","us":"media/us/goose__us_1.mp3","img":["media/ldoce/img/goose.jpg"]},"oxford":{"phon":"ɡuːs","pos":"noun","senses":[{"en":"a bird like a large duck with a long neck. Geese either live wild or are kept on farms.","cn":"鹅","g":"[countable]"},{"en":"meat from a goose","cn":"鹅肉","g":"[uncountable]","ex":{"en":"roast goose","cn":"烤鹅"}},{"en":"a female goose","cn":"雌鹅","g":"[countable]"},{"en":"a silly person","cn":"傻瓜；笨蛋","g":"[countable]","lab":"old-fashioned, informal，，"},{"en":"to touch or press somebody’s bottom quickly","cn":"戳（或捏）（某人）臀部","ex":{"en":"Jack goosed her as she reached for a file.","cn":"当她伸手去拿文件夹时，杰克刺激了她。"},"pos":"verb"},{"en":"to make something move or work faster","cn":"推动；促进；激励","lab":"North American English","ex":{"en":"The government has done everything possible to goose the economy along.","cn":"政府已尽一切可能推动经济发展。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鹅","en":"A goose is a large bird that has a long neck and webbed feet. Geese are often farmed for their meat."},{"pos":"N-UNCOUNT 不可数名词","cn":"鹅肉","en":"Goose is the meat from a goose that has been cooked.","ex":{"en":"...roast goose.","cn":"烤鹅"}},{"pos":"PHRASE 短语","cn":"阻挠；破坏…的计划","en":"If you cook someone's goose, you prevent their plans from succeeding.","ex":{"en":"He said that what they were up to would cook Krasky's goose.","cn":"他说他们暗中进行的阴谋可能会使克拉斯基的计划流产。"}},{"pos":"PHRASE 短语","cn":"杀鸡取卵；自绝财源","en":"If someone kills the goose that lays the golden egg, they harm or destroy the person or thing that gives them their money, power, or advantage.","ex":{"en":"Unregulated tourism can kill the goose that laid their golden egg.","cn":"旅游业的无序发展无异于杀鸡取卵。"}},{"pos":"PHRASE 短语","cn":"适于此者适于彼；应该一视同仁","en":"If you say what's sauce for the goose is sauce for the gander, you mean what is acceptable for one person in a particular situation should be acceptable for another person in a similar situation."}]},"examples":[{"en":"roast goose","cn":"烤鹅"}]},"gold":{"media":{"uk":"media/uk/gold__gb_1.mp3","us":"media/us/gold__us_1.mp3"},"oxford":{"phon":"ɡəʊld","pos":"noun","senses":[{"en":"a chemical element. Gold is a yellow precious metal used for making coins, jewellery, beautiful objects, etc.","cn":"金","g":"[uncountable]","ex":{"en":"gold coins/jewellery","cn":"金币；金首饰"}},{"en":"money, jewellery, etc. that is made of gold","cn":"金币；金饰品；黄金制品","g":"[uncountable]","ex":{"en":"The hotel was dripping with (= decorated with a lot of) gold.","cn":"这家酒店到处都是黄金饰品。"}},{"en":"a medal made of gold that is given to the winner of a race or competition","cn":"金牌；金质奖章","g":"[uncountable, countable]","ex":{"en":"The team look set to win Olympic gold.","cn":"这个队看来可能会拿奥运会金牌。"}},{"en":"the colour of gold","cn":"金色；金黄色","g":"[uncountable, countable]","ex":{"en":"a sunset of burnished gold","cn":"金色的夕阳"}},{"en":"bright yellow in colour, like gold","cn":"金色的","ex":{"en":"The company name was spelled out in gold letters.","cn":"该公司的名称用烫金字母拼成。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"黄金","en":"Gold is a valuable, yellow-coloured metal that is used for making jewellery and ornaments, and as an international currency.","ex":{"en":"...a sapphire set in gold","cn":"镶嵌在黄金上的蓝宝石"}},{"pos":"N-UNCOUNT 不可数名词","cn":"金饰物；黄金制品","en":"Gold is jewellery and other things that are made of gold.","ex":{"en":"We handed over all our gold and money.","cn":"我们将所有的金首饰和钱都交了出来。"}},{"pos":"COLOUR 颜色词","cn":"金色；金黄色","en":"Something that is gold is a bright yellow colour, and is often shiny.","ex":{"en":"I'd been wearing Michel's black and gold shirt.","cn":"我一直都穿着米歇尔那件黑色和金色相间的衬衫。"}},{"pos":"N-VAR 可变名词","cn":"同gold medal","en":"A gold is the same as a gold medal .","ex":{"en":"His ambition was to win gold at the Atlanta Games in 1996","cn":"他的志向是在1996年亚特兰大奥运会上夺取金牌。"}},{"pos":"PHRASE 短语","cn":"（小孩）规规矩矩的,乖巧的","en":"If you say that a child is being as good as gold, you are emphasizing that they are behaving very well and are not causing you any problems.","ex":{"en":"The boys were as good as gold on our walk.","cn":"我们散步的时候，这帮小男孩表现得很乖。"}},{"pos":"PHRASE 短语","cn":"一颗金子般的心；赤子之心","en":"If you say that someone has a heart of gold, you are emphasizing that they are very good and kind to other people.","ex":{"en":"They are all good boys with hearts of gold. They would never steal.","cn":"他们都是有着金子般心灵的好孩子，绝不会干偷摸扒窃之事。"}},{"pos":"PHRASE 短语","cn":"期望得到的一大笔钱，未来的一桶金（英国英语中亦作a crock of gold）","en":"Money that someone hopes they will get in the future is sometimes referred to as a pot of gold. Also a crock of gold, mainly in British English.","ex":{"en":"I would rather be honest with people than tell them that there is going to be some pot of gold at the end of the rainbow.","cn":"我宁肯实话实说也不愿意给予他们不切实际的期望。"}},{"pos":"See also:","cn":"","en":"to strike gold→see: ; worth one's weight in gold→see: ;"}]},"examples":[{"en":"The team look set to win Olympic gold.","cn":"这个队看来可能会拿奥运会金牌。"},{"en":"I love the reds and golds of autumn.","cn":"我喜欢秋天的火红色和金黄色。"}]},"governed":{"lemma":"govern"},"gone":{"media":{"uk":"media/uk/gone__gb_2.mp3","us":"media/us/gone__us_3.mp3"},"oxford":{"phon":"ɡɒn","pos":"adjective","senses":[{"en":"used up","cn":"用完了；用光了","ex":{"en":"‘Where's the coffee?’ ‘It's all gone.’","cn":"“咖啡在哪儿？”“喝光了。”"}},{"en":"having left a place; away from a place","cn":"走了；离开了；不在","ex":{"en":"‘Is Tom here?’ ‘No, he was gone before I arrived.’","cn":"“汤姆在这儿吗？”“不在，我来之前他就走了。”"}},{"en":"used to say that a particular situation no longer exists","cn":"不复存在；一去不复返","lab":"formal","ex":{"en":"The days are gone when you could leave your door unlocked at night.","cn":"夜不闭户的时代已经一去不复返了。"}},{"en":"having been pregnant for the length of time mentioned","cn":"怀孕…时间了","lab":"British English, informal，，","ex":{"en":"She's seven months gone.","cn":"她怀孕七个月了。"}},{"en":"later than the time mentioned","cn":"晚于；已过","ex":{"en":"It's gone six already.","cn":"已经过六点了。"},"pos":"preposition"}]},"collins":{"senses":[{"pos":"","cn":"","en":"Gone is the past participle of go ."},{"pos":"ADJ 形容词","cn":"离开的；过去的；不复存在的","en":"When someone is gone, they have left the place where you are and are no longer there. When something is gone, it is no longer present or no longer exists.","ex":{"en":"While he was gone she had tea with the Colonel","cn":"他不在时她跟上校一起喝了茶。"}},{"pos":"PREP 介词","cn":"晚于，超过（某一时间）","en":"If you say it is gone a particular time, you mean it is later than that time.","ex":{"en":"It was just gone 7 o'clock this evening when I finished.","cn":"今晚我做完的时候刚过7点。"}}]},"examples":[{"en":"‘Is Tom here?’ ‘No, he was gone before I arrived.’ “","cn":"汤姆在这儿吗？” “不在，我来之前他就走了。”"},{"en":"The days are gone when you could leave your door unlocked at night.","cn":"夜不闭户的时代已经一去不复返了。"}]},"governor":{"media":{"uk":"media/uk/governor__gb_1.mp3","us":"media/us/governor__us_1.mp3"},"oxford":{"phon":"ˈɡʌvənə(r)","pos":"noun","senses":[{"en":"a person who is the official head of a country or region that is governed by another country","cn":"统治者；管辖者；总督","ex":{"en":"the former governor of the colony","cn":"该殖民地的前总督"}},{"en":"a person who is chosen to be in charge of the government of a state in the US","cn":"（美国的）州长","ex":{"en":"the governor of Arizona","cn":"亚利桑那州州长"}},{"en":"a member of a group of people who are responsible for controlling an institution such as a school, a college or a hospital","cn":"（学校、学院、医院等机构的）董事，理事","lab":"especially British English","ex":{"en":"One way of getting things changed is to become a school governor.","cn":"要使情况发生改变，一个办法是成为学校的董事。"}},{"en":"a person who is in charge of an institution","cn":"主管；机构负责人；总裁","lab":"British English","ex":{"en":"A copy of the report was sent to the prison governor.","cn":"报告的一份复印件送交给了监狱长。"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"州长；省长；总督","en":"In some systems of government, a governor is a person who is in charge of the political administration of a region or state.","ex":{"en":"He was governor of the province in the late 1970s","cn":"他在20世纪70年代末担任该省的省长。"}},{"pos":"N-COUNT 可数名词","cn":"（学校、医院等的)董事,理事","en":"A governor is a member of a committee which controls an organization such as a school or a hospital.","ex":{"en":"Governors are using the increased powers given to them to act against incompetent headteachers.","cn":"董事们运用赋予他们的更大权力罢免不称职的校长。"}},{"pos":"N-COUNT 可数名词","cn":"（英国一些机构的）主管,总裁","en":"In some British institutions, the governor is the most senior official, who is in charge of the institution.","ex":{"en":"The incident was reported to the prison governor.","cn":"这一事件已汇报给监狱长。"}}]},"examples":[{"en":"( informal ) I can't decide. I'll have to ask the governor (= the man in charge, who employs sb).","cn":"我做不了主，我得问问老板。"},{"en":"the former governor of the colony","cn":"该殖民地的前总督"}]},"gossip":{"media":{"uk":"media/uk/gossip__gb_1.mp3","us":"media/us/gossip__us_1.mp3"},"oxford":{"phon":"ˈɡɒsɪp","pos":"noun","senses":[{"en":"informal talk or stories about other people’s private lives, which may be unkind or not true","cn":"流言蜚语；闲言碎语","g":"[uncountable]","lab":"usually disapproving","ex":{"en":"Don't believe all the gossip you hear.","cn":"别对那些道听途说都信以为真。"}},{"en":"a conversation about other people and their private lives","cn":"闲聊","g":"[countable, usually singular]","ex":{"en":"I love a good gossip.","cn":"我喜欢闲聊天。"}},{"en":"a person who enjoys talking about other people’s private lives","cn":"喜欢传播流言蜚语的人；爱说长道短（或说三道四）的人","g":"[countable]","lab":"disapproving","ex":{"en":"The people I work with are terrible gossips.","cn":"和我一起工作的人都是可怕的八卦者。"}},{"en":"to talk about other people’s private lives, often in an unkind way","cn":"传播流言蜚语；说三道四；说长道短","ex":{"en":"I can't stand here gossiping all day.","cn":"我不能整天站在这儿闲聊啊。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"流言蜚语；小道消息；闲话","en":"Gossip is informal conversation, often about other people's private affairs.","ex":{"en":"He spent the first hour talking gossip","cn":"他头一个小时都在闲聊。"}},{"pos":"V-RECIP 相互动词","cn":"闲聊；说长道短","en":"If you gossip with someone, you talk informally, especially about other people or local events. You can also say that two people gossip .","ex":{"en":"We spoke, debated, gossiped into the night","cn":"我们交谈着，争论着，闲聊着，一直持续到晚上。"}},{"pos":"N-COUNT 可数名词","cn":"爱说长道短的人","en":"If you describe someone as a gossip, you mean that they enjoy talking informally to people about the private affairs of others.","ex":{"en":"He was a vicious gossip.","cn":"他总是喜欢说别人的坏话。"}}]},"examples":[{"en":"The gossip was that he had lost a fortune on the stock exchange.","cn":"有小道消息说他在股票交易中赔了一大笔钱。"},{"en":"Tell me all the latest gossip!","cn":"把最新的小道消息都讲给我听听吧！"}]},"god":{"media":{"uk":"media/uk/god__gb_1.mp3","us":"media/us/god__us_1.mp3"},"oxford":{"phon":"ɡɒd","pos":"noun","senses":[{"en":"the being or spirit that is worshipped and is believed to have created the universe","cn":"上帝；天主；真主","g":"[singular]","lab":"North American English","ex":{"en":"Do you believe in God?","cn":"你信仰上帝吗？"}},{"en":"(in some religions) a being or spirit who is believed to have power over a particular part of nature or who is believed to represent a particular quality","cn":"（某些宗教中主宰某个领域的）神","g":"[countable]","ex":{"en":"the Hindu god Vishnu","cn":"印度教神毗湿奴"}},{"en":"a person who is loved or admired very much by other people","cn":"极受崇拜的人；被崇拜的偶像","g":"[countable]","ex":{"en":"To her fans she's a god.","cn":"对她的狂热崇拜者来说，她就是偶像。"}},{"en":"something to which too much importance or attention is given","cn":"受到过分崇尚（或推崇）的事物","g":"[countable]","ex":{"en":"Money is his god.","cn":"钱就是他的命。"}},{"en":"the seats that are high up at the back of a theatre","cn":"（剧院中的）顶层楼座，最高楼座","g":"[plural]","lab":"British English, informal，，","ex":{"en":"We could only afford to sit in the gods.","cn":"我们只能坐在神位上。"}}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"上帝；天主；真主","en":"The name God is given to the spirit or being who is worshipped as the creator and ruler of the world, especially by Jews, Christians, and Muslims.","ex":{"en":"He believes in God","cn":"他信奉上帝。"}},{"pos":"CONVENTION 惯用语","cn":"（表示强调所说的话，或表示惊讶、恐惧或激动）啊呀，天啊，天哪（可能具冒犯意味）","en":"People sometimes use God in exclamations to emphasize something that they are saying, or to express surprise, fear, or excitement. This use could cause offence.","ex":{"en":"God, how I hated him!","cn":"啊呀！我恨死他了！"}},{"pos":"N-COUNT 可数名词","cn":"神","en":"In many religions, a god is one of the spirits or beings that are believed to have power over a particular part of the world or nature.","ex":{"en":"...Pan, the God of nature.","cn":"自然之神，潘"}},{"pos":"N-COUNT 可数名词","cn":"极受尊崇的人；影响极大的人","en":"Someone who is admired very much by a person or group of people, and who influences them a lot, can be referred to as a god .","ex":{"en":"To his followers he was a god.","cn":"在追随者眼中，他就是神。"}},{"pos":"PHRASE 短语","cn":"愿上帝阻止这样的事情；但愿这样的事不会发生","en":"If you say God forbid, you are expressing your hope that something will not happen.","ex":{"en":"If, God forbid, something goes wrong, I don't know what I would do.","cn":"如果哪儿出点儿岔子，我会不知所措的，但愿这样的事情不会发生。"}},{"pos":"PHRASE 短语","cn":"上帝的恩赐；十全十美的人","en":"If a person thinks they are God's gift to someone or something, they think they are perfect or extremely good.","ex":{"en":"Are men god's gift to women? Some of them think they are.","cn":"男人是上帝赐予女人的礼物吗？有些男人就是这样认为的。"}},{"pos":"PHRASE 短语","cn":"（警告语）愿上帝保佑你","en":"You use God help you to warn someone that something unpleasant will happen to them if they do a particular thing.","ex":{"en":"God help him if he gets in my way","cn":"他要是跟我作对，那就让上帝保佑他吧。"}},{"pos":"PHRASE 短语","cn":"愿上帝保佑…","en":"If you feel sorry for someone because they are in a difficult or unpleasant situation, especially if you think that nobody can help them, you can say God help them.","ex":{"en":"'God help them,' he said. 'They're beyond help.'","cn":"“愿上帝保佑他们吧，”他说，“谁也帮不了他们了。”"}},{"pos":"PHRASE 短语","cn":"真讨厌；真烦人","en":"If you say God help us, you mean that you have negative feelings about the person or situation you are talking about.","ex":{"en":"The first song is 11 minutes long, the last nearly the same, and, God help us, there's a drum solo along the way.","cn":"第一首歌有11分钟长，最后一首也差不多长，唉，上帝啊，中间还有一个击鼓独奏。"}},{"pos":"PHRASE 短语","cn":"（表示强调）只有上帝知道，天晓得","en":"You can say God knows ,God only knows, or God alone knows to emphasize that you do not know something.","ex":{"en":"Gunga spoke God knows how many languages","cn":"天晓得贡嘎会讲多少门语言。"}},{"pos":"PHRASE 短语","cn":"（表示不知道答案）天晓得","en":"If someone says God knows in reply to a question, they mean that they do not know the answer.","ex":{"en":"'Where is he now?' 'God knows.'","cn":"“他现在在哪里？”“天晓得。”"}},{"pos":"PHRASE 短语","cn":"（基督教的）牧师，神父","en":"The term a man of God is sometimes used to refer to Christian priests or ministers.","ex":{"en":"I am a man of God.","cn":"我是个牧师。"}},{"pos":"PHRASE 短语","cn":"（用来强调生气、懊恼或吃惊）究竟什么/ 究竟为什么/究竟如何","en":"If someone uses such expressions as what in God's name ,why in God's name, or how in God's name, they are emphasizing how angry, annoyed, or surprised they are.","ex":{"en":"What in God's name do you expect me to do?","cn":"你究竟要我做什么？"}},{"pos":"PHRASE 短语","cn":"俨然一副上帝的样子；表现得无所不能","en":"If someone plays God, they act as if they have unlimited power and can do anything they want.","ex":{"en":"You have no right to play God in my life!","cn":"你无权对我的人生指手画脚！"}},{"pos":"PHRASE 短语","cn":"（强调愿望之强烈）老天保佑，求求上天帮忙","en":"You say please God to emphasize a strong hope, wish, or desire that you have.","ex":{"en":"Please God, let him telephone me now.","cn":"拜托老天了，让他现在就给我来个电话吧。"}},{"pos":"PHRASE 短语","cn":"（表示强调）我向上帝祈祷/我真诚地希望/我向上帝发誓","en":"You can use God in expressions such as I hope to God, or I wish to God, or I swear to God, in order to emphasize what you are saying.","ex":{"en":"I hope to God they are paying you well","cn":"我真希望他们给你一份好的酬劳。"}},{"pos":"PHRASE 短语","cn":"如系天意；如一切顺利","en":"If you say God willing, you are saying that something will happen if all goes well.","ex":{"en":"God willing, there will be a breakthrough.","cn":"如果一切顺利，将会取得突破性的进展。"}},{"pos":"","cn":"","en":"to put the fear of God into someone→see: ; honest to God→see: ; in the lap of the gods→see: ; for God's sake→see: ; thank God→see: ;"}]},"examples":[{"en":"It is unfair to ask doctors to play God and end someone's life.","cn":"让医生担当上帝的角色去结束一个人的生命并不公平。"},{"en":"He seems to think he's God's gift to women.","cn":"他似乎认为自己是上帝赐给女人的礼物。"}]},"goddess":{"media":{"uk":"media/uk/goddess__gb_1.mp3","us":"media/us/goddess__us_1.mp3"},"oxford":{"phon":"ˈɡɒdes","pos":"noun","senses":[{"en":"a female god","cn":"女神","ex":{"en":"Diana, the goddess of hunting","cn":"狩猎女神狄安娜"}},{"en":"a woman who is loved or admired very much by other people","cn":"极受崇拜（或敬慕）的女人","ex":{"en":"a screen goddess (= a female film star)","cn":"银幕女神"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"女神","en":"In many religions, a goddess is a female spirit or being that is believed to have power over a particular part of the world or nature.","ex":{"en":"...Athena, the goddess of war.","cn":"战争女神雅典娜"}}]},"examples":[{"en":"a screen goddess (= a female film/movie star)","cn":"银幕女神"},{"en":"Diana, the goddess of hunting","cn":"狩猎女神狄安娜"}]},"go":{"media":{"uk":"media/uk/go__gb_1.mp3","us":"media/us/go__us_1.mp3"},"oxford":{"phon":"ɡəʊ","pos":"verb","senses":[{"en":"to move or travel from one place to another","cn":"去；走","g":"[intransitive]","lab":"North American English","sc":"move/travel","ex":{"en":"She went into her room and shut the door behind her.","cn":"她走进自己的房间，把门关上。"}},{"en":"to move or travel, especially with somebody else, to a particular place or in order to be present at an event","cn":"（尤指与某人）去（某处或出席某项活动）","g":"[intransitive]","sc":"move/travel","ex":{"en":"Are you going to Dave's party?","cn":"你要去参加戴夫的聚会吗？"}},{"en":"to move or travel in a particular way or over a particular distance","cn":"移动，旅行，行走（指方式或距离）","g":"[intransitive]","sc":"move/travel","ex":{"en":"He's going too fast.","cn":"他走得太快。"}},{"en":"to move in a particular way or while doing something else","cn":"（以某种方式）移动；在移动中做","g":"[intransitive]","sc":"move/travel","ex":{"en":"She crashed into a waiter and his tray of drinks went flying.","cn":"她一下子撞到侍者身上，弄得他托盘里的饮料四处飞溅。"}},{"en":"to leave one place in order to reach another","cn":"离开；离去；出发","g":"[intransitive]","sc":"leave","ex":{"en":"I must be going now.","cn":"我现在得走了。"}},{"en":"to leave a place and do something different","cn":"去做（某事）","g":"[intransitive]","lab":"British English","sc":"leave","ex":{"en":"to go on a journey/tour/trip/cruise","cn":"去旅行／观光游览／短途旅行／乘船旅游"}},{"en":"to visit or attend a place for a particular purpose","cn":"（为某目的）去（某处）","g":"[intransitive]","lab":"British English","sc":"visit/attend","ex":{"en":"to go to school/college/university","cn":"上学；上大学"}},{"en":"to look at a particular page or website","cn":"查看（页面或网站）","sc":"visit/attend","ex":{"en":"She went on Facebook and changed her relationship status.","cn":"她上脸书更新了她的感情状态。"}},{"en":"to leave a place or travel to a place in order to take part in an activity or a sport","cn":"去参加，去从事（某项活动或运动）","g":"[intransitive]","sc":"swimming/fishing/jogging, etc.","ex":{"en":"to go for a walk","cn":"去散步"}},{"en":"to be sent or passed somewhere","cn":"被发送；被传递","g":"[intransitive]","sc":"be sent","ex":{"en":"I want this memo to go to all managers.","cn":"我想让这份备忘录送交到所有经理手中。"}},{"en":"used to talk about how quickly or slowly time seems to pass","cn":"流逝；消逝；过去","g":"[intransitive]","sc":"time","ex":{"en":"Hasn't the time gone quickly?","cn":"时光过得真快，是不是？"}},{"en":"to stop existing; to be lost or stolen","cn":"不复存在；不见了；丢失；失窃","g":"[intransitive]","sc":"disappear","ex":{"en":"Has your headache gone yet?","cn":"你还头痛吗？"}},{"en":"to lead or extend in a particular direction","cn":"通往；延伸到","g":"[intransitive]","sc":"lead","ex":{"en":"Where does this road go?","cn":"这条路通到哪里？"}},{"en":"to have as a usual or correct position; to be placed","cn":"被放置，被置于，被安放（在通常或合适的位置）","g":"[intransitive]","sc":"place/space","ex":{"en":"This dictionary goes on the top shelf.","cn":"这部词典放在书架最上层。"}},{"en":"used to say that something does/did not fit into a particular place or space","cn":"（不）适合；放（不）进","g":"[intransitive]","sc":"place/space","ex":{"en":"My clothes won't all go in that one suitcase.","cn":"一个手提箱装不下我所有的衣服。"}},{"en":"used to talk about how well or badly something makes progress or succeeds","cn":"（事情）进展，进行","g":"[intransitive]","sc":"progress","ex":{"en":"‘How did the interview go?’ ‘It went well, thank you.’","cn":"“面试情况如何？”“非常顺利，谢谢。”"}},{"en":"used in many expressions to show that somebody/something has reached a particular state/is no longer in a particular state","cn":"进入…状态；处于…状况；脱离…状态","g":"[intransitive]","sc":"state/condition","ex":{"en":"She went to sleep.","cn":"她睡着了。"}},{"en":"to become different in a particular way, especially a bad way","cn":"（尤指朝坏的方面）变成，变为，变得","sc":"state/condition","ex":{"en":"to go crazy/mad/nuts/insane","cn":"发狂；发疯；失去理智"}},{"en":"to live or move around in a particular state","cn":"（在某种状态下）生活，过活，移动","g":"[intransitive]","sc":"state/condition","ex":{"en":"to go naked/barefoot","cn":"光着身子；赤着脚"}},{"en":"to spend a period of time in a particular way","cn":"以特定方式度过一段时间","g":"[intransitive]","sc":"state/condition","ex":{"en":"They went for two weeks without receiving any news.","cn":"他们两个星期没有收到任何消息。"}},{"en":"to not be noticed, reported, etc.","cn":"未被注意到（或报告等）","g":"[intransitive]","sc":"state/condition","ex":{"en":"Pippa's absence went unnoticed.","cn":"皮帕的缺席没有引起人们的注意。"}},{"en":"to make a particular sound or movement","cn":"发出（某种声音）；做（某种动作）","g":"[intransitive]","sc":"sound/movement","ex":{"en":"The gun went ‘bang’.","cn":"枪“砰”的一声响了。"}},{"en":"to be sounded as a signal or warning","cn":"发出信号（或警告）","g":"[intransitive]","sc":"sound/movement","ex":{"en":"The whistle went for the end of the game.","cn":"比赛结束的哨声响了。"}},{"en":"if a number will go into another number, it is contained in that number an exact number of times","cn":"除尽；除","g":"[intransitive]","lab":"North American English","sc":"numbers","ex":{"en":"3 into 12 goes 4 times.","cn":"3 除 12 得 4。"}},{"en":"to combine well with something","cn":"与某物相配（或协调、和谐）","sc":"combine well","ex":{"en":"Does this jacket go with this skirt?","cn":"这件上衣与这条裙子相配吗？"}},{"en":"used to talk about what tune or words a song or poem has or what happens in a story","cn":"（歌曲）唱道；（诗歌）写道；（歌词或故事）内容是","g":"[intransitive, transitive]","sc":"song/story","ex":{"en":"How does that song go?","cn":"那首歌怎么唱？"}},{"en":"to say","cn":"说","g":"[transitive]","lab":"informal","sc":"say","ex":{"en":"I asked ‘How much?’ and he goes, ‘Fifty’ and I go, ‘Fifty? You must be joking!’","cn":"我问：“多少钱？”他回答说：“五十。”我又说：“五十？你是在开玩笑吧！”"}},{"en":"to start an activity","cn":"开始（活动）","g":"[intransitive]","sc":"start","ex":{"en":"I'll say ‘One, two, three, go!’ as a signal for you to start.","cn":"我喊“一、二、三，开始！”作为你开始的信号。"}},{"en":"if a machine goes, it works","cn":"运行；运转；工作","g":"[intransitive]","sc":"machine","ex":{"en":"This clock doesn't go.","cn":"这钟不走了。"}},{"en":"used to talk about wanting to get rid of somebody/something","cn":"（必须或可以）辞掉（或扔掉、废弃）","g":"[intransitive]","sc":"be thrown out","ex":{"en":"The old sofa will have to go.","cn":"那旧沙发该扔掉了。"}},{"en":"to get worse; to become damaged or stop working correctly","cn":"变坏；损坏；不起作用","g":"[intransitive]","sc":"not work","ex":{"en":"Her sight is beginning to go.","cn":"她的视力开始下降。"}},{"en":"to die. People say ‘go’ to avoid saying ‘die’.","cn":"走（委婉说法，与 die 同义）","g":"[intransitive]","sc":"die","ex":{"en":"You can't take your money with you when you go.","cn":"你不可能把钱带进棺材。"}},{"en":"when money goes, it is spent or used for something","cn":"用于；花掉","g":"[intransitive]","sc":"money","ex":{"en":"I don't know where the money goes!","cn":"我不知道钱都花到什么地方去了！"}},{"en":"to be sold","cn":"被卖掉；被出售","g":"[intransitive]","sc":"money","ex":{"en":"We won't let the house go for less than $200 000.","cn":"这房子低于 20 万美元我们是不会卖的。"}},{"en":"to be willing to pay a particular amount of money for something","cn":"愿出价购买","g":"[intransitive]","sc":"money","ex":{"en":"He's offered £3 000 for the car and I don't think he'll go any higher.","cn":"他出价 3 000 英镑买这辆汽车，我看他不会愿意再多付了。"}},{"en":"to help; to play a part in doing something","cn":"有助于；促成；起作用","g":"[intransitive]","sc":"help","ex":{"en":"This all goes to prove my theory.","cn":"这一切都有助于证明我的说法是对的。"}},{"en":"to be available","cn":"可得到；可买到；现成可用","g":"[intransitive]","lab":"informal","sc":"be available","ex":{"en":"There just aren't any jobs going in this area.","cn":"此地几乎没有工作可找。"}},{"en":"to use a toilet","cn":"用厕所；上厕所","g":"[intransitive]","lab":"informal","sc":"use toilet","ex":{"en":"Do you need to go, Billy?","cn":"你要上厕所吗，比利？"}},{"en":"a person’s turn to move or play in a game or an activity","cn":"（游戏或活动中）轮到的机会","g":"[countable]","lab":"British English","ex":{"en":"Whose go is it?","cn":"轮到谁了？"},"pos":"noun"},{"en":"an attempt at doing something","cn":"（做某事的）尝试，一番努力","g":"[countable]","ex":{"en":"It took three goes to get it right.","cn":"试了三次才把它弄好。"},"pos":"noun"},{"en":"energy and enthusiasm","cn":"精力；活力；热情；干劲","g":"[uncountable]","lab":"British English","ex":{"en":"Mary's always got plenty of go.","cn":"玛丽总是精力充沛。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"去；行进","en":"When you go somewhere, you move or travel there.","ex":{"en":"We went to Rome","cn":"我们去了罗马。"}},{"pos":"VERB 动词","cn":"离开；走","en":"When you go, you leave the place where you are.","ex":{"en":"Let's go","cn":"我们走吧。"}},{"pos":"VERB 动词","cn":"去参加，去从事（某活动）","en":"You use go to say that someone leaves the place where they are and does an activity, often a leisure activity.","ex":{"en":"We went swimming very early","cn":"我们很早就去游泳了。"}},{"pos":"VERB 动词","cn":"去做…（可用go to do, 也可用go and do，美国英语中还可用go do，然而一般说 went and did）","en":"When you go to do something, you move to a place in order to do it and you do it. You can also go and do something, and in American English, you can go do something. However, you always say that someone went and did something.","ex":{"en":"His second son, Paddy, had gone to live in Canada","cn":"他的二儿子帕迪去加拿大生活了。"}},{"pos":"VERB 动词","cn":"去（上学、上班或教堂）","en":"If you go to school, work, or church, you attend it regularly as part of your normal life.","ex":{"en":"She will have to go to school","cn":"她将不得不去上学。"}},{"pos":"VERB 动词","cn":"（路）通向，延伸到，位于","en":"When you say where a road or path goes, you are saying where it begins or ends, or what places it is in.","ex":{"en":"There's a mountain road that goes from Blairstown to Millbrook Village.","cn":"有一条山路从布莱尔斯敦通向米尔布鲁克村。"}},{"pos":"VERB 动词","cn":"（用于否定表达中，表示对所提到行为不赞成或不允许某人有这种行为）","en":"You can use go in expressions such as 'don't go telling everybody', in order to express disapproval of the kind of behaviour you mention, or to tell someone not to behave in that way.","ex":{"en":"You don't have to go running upstairs every time she rings","cn":"用不着她一来电话你就往楼上跑。"}},{"pos":"VERB 动词","cn":"（与further,beyond等词连用，表示某事的进展或程度）","en":"You can use go with words like 'further' and 'beyond' to show the degree or extent of something.","ex":{"en":"He went even further in his speech to the conference","cn":"他在大会发言中作了更进一步的阐述。"}},{"pos":"VERB 动词","cn":"（时间）过去，流逝","en":"If you say that a period of time goes quickly or slowly, you mean that it seems to pass quickly or slowly.","ex":{"en":"The weeks go so quickly!","cn":"这几周过得真快！"}},{"pos":"VERB 动词","cn":"（钱）用于，花掉","en":"If you say where money goes, you are saying what it is spent on.","ex":{"en":"Most of my money goes on bills","cn":"我的钱大部分用来支付各种账单。"}},{"pos":"VERB 动词","cn":"由…得到；授予；归于","en":"If you say that something goes to someone, you mean that it is given to them.","ex":{"en":"A lot of credit must go to the chairman and his father","cn":"很大一部分功劳应归于主席和他的父亲。"}},{"pos":"VERB 动词","cn":"上，参加（电视或电台节目）","en":"If someone goes on television or radio, they take part in a television or radio programme.","ex":{"en":"The Turkish president has gone on television to defend stringent new security measures","cn":"土耳其总统上电视为严格的新安全措施进行辩护。"}},{"pos":"VERB 动词","cn":"被除掉；被去掉","en":"If something goes, someone gets rid of it.","ex":{"en":"The Institute of Export now fears that 100,000 jobs will go","cn":"现在出口协会担心将失去10万个工作机会。"}},{"pos":"VERB 动词","cn":"（常指被迫）辞职","en":"If someone goes, they leave their job, usually because they are forced to.","ex":{"en":"He had made a humiliating tactical error and he had to go.","cn":"他犯了一个让他颜面尽失的战术错误，只得引咎辞职。"}},{"pos":"VERB 动词","cn":"被放入；包含于","en":"If something goes into something else, it is put in it as one of the parts or elements that form it.","ex":{"en":"...the really interesting ingredients that go into the dishes that we all love to eat.","cn":"我们都爱吃的菜肴里所放入的十分有趣的原料"}},{"pos":"VERB 动词","cn":"装得进；塞得进","en":"If something goes in a particular place, it fits in that place or should be put there because it is the right size or shape.","ex":{"en":"He was trying to push it through the hole and it wouldn't go.","cn":"他想将它从这个洞里推过去，但却怎么也过不去。"}},{"pos":"VERB 动词","cn":"（按惯例应）置于","en":"If something goes in a particular place, it belongs there or should be put there, because that is where you normally keep it.","ex":{"en":"The shoes go on the shoe shelf","cn":"鞋子放在鞋架上。"}},{"pos":"VERB 动词","cn":"除尽；除","en":"If you say that one number goes into another number a particular number of times, you are dividing the second number by the first.","ex":{"en":"Six goes into thirty five times.","cn":"6除30得5。"}},{"pos":"VERB 动词","cn":"（官能）衰退，下降","en":"If one of a person's senses, such as their sight or hearing, is going, it is getting weak and they may soon lose it completely.","ex":{"en":"His eyes are going; he says he has glaucoma","cn":"他的视力在下降，他说自己得了青光眼。"}},{"pos":"VERB 动词","cn":"（灯泡、引擎等)损坏，报废，无法正常运转","en":"If something such as a light bulb or a part of an engine is going, it is no longer working properly and will soon need to be replaced.","ex":{"en":"I thought it looked as though the battery was going.","cn":"我看电池好像该换了。"}},{"pos":"VERB 动词","cn":"奄奄一息；去世","en":"If you say that someone is going or has gone, you are saying in an indirect way that they are dying or are dead.","ex":{"en":"'Any hope?' — 'No, he's gone.'","cn":"“还有希望吗？”——“没有，他已经死了。”"}},{"pos":"V-LINK 连系动词","cn":"变得；成为","en":"You can use go to say that a person or thing changes to another state or condition. For example, if someone goes crazy, they become crazy, and if something goes green, it changes colour and becomes green.","ex":{"en":"I'm going bald","cn":"我开始秃头了。"}},{"pos":"V-LINK 连系动词","cn":"（表示是否穿戴或拥有某物）","en":"You can use go when indicating whether or not someone wears or has something. For example, if someone goes barefoot, they do not wear any shoes.","ex":{"en":"The baby went naked on the beach","cn":"这个小宝贝光着身子在沙滩上。"}},{"pos":"V-LINK 连系动词","cn":"（用在以un开头的形容词之前表示某事没有发生）","en":"You can use go before adjectives beginning with 'un-' to say that something does not happen. For example, if something goes unheard, nobody hears it.","ex":{"en":"As President, he affirmed that no tyranny went unnoticed.","cn":"他以总统的名义宣称没有对任何暴行置若罔闻。"}},{"pos":"VERB 动词","cn":"进展；进行","en":"You use go to talk about the way something happens. For example, if an event or situation goes well, it is successful.","ex":{"en":"She says everything is going smoothly","cn":"她说一切进展顺利。"}},{"pos":"VERB 动词","cn":"（机器或装置）运转，运行，工作","en":"If a machine or device is going, it is working.","ex":{"en":"What about my copier? Can you get it going again?","cn":"我的复印机怎么样了？你能把它修好吗？"}},{"pos":"VERB 动词","cn":"（铃等）鸣响","en":"If a bell goes, it makes a noise, usually as a signal for you to do something.","ex":{"en":"The bell went for the break.","cn":"课间休息铃响了。"}},{"pos":"V-RECIP 相互动词","cn":"（与…）相配；（与…）相称","en":"If something goes with something else, or if two things go together, they look or taste nice together.","ex":{"en":"I was searching for a pair of grey gloves to go with my new gown","cn":"我在找一副跟我的新礼服相配的灰色手套。"}},{"pos":"VERB 动词","cn":"（用于引出要引用的话）","en":"You use go to introduce something you are quoting. For example, you say the story goes or the argument goes just before you quote all or part of it.","ex":{"en":"The story goes that she went home with him that night","cn":"据说她那天晚上跟他一起回了家。"}},{"pos":"VERB 动词","cn":"发出…声响","en":"You use go when indicating that something makes or produces a sound. For example, if you say that something goes 'bang', you mean it produces the sound 'bang'.","ex":{"en":"She stopped in front of a painting of a dog and she started going 'woof woof'","cn":"她在一幅狗的画像前停下来，开始“汪汪”地学起狗叫来。"}},{"pos":"VERB 动词","cn":"说（代替say，表示引述他人的话或认为他们要说的话）","en":"You can use go instead of 'say' when you are quoting what someone has said or what you think they will say.","ex":{"en":"They say 'Tom, shut up' and I go 'No, you shut up'","cn":"他们说：“汤姆，你闭嘴！”我说：“才不呢，你们闭嘴！”"}},{"pos":"N-COUNT 可数名词","cn":"尝试；努力","en":"A go is an attempt at doing something.","ex":{"en":"I always wanted to have a go at football","cn":"我一直都想试试踢足球。"}},{"pos":"N-COUNT 可数名词","cn":"（牌戏、下棋等中）轮到的顺序","en":"If it is your go in a game, it is your turn to do something, for example to play a card or move a piece.","ex":{"en":"I'm two behind you but it's your go","cn":"我落后你两步，但现在轮到你走了。"}},{"pos":"PHRASE 短语","cn":"全力以赴；不遗余力地做","en":"If you go all out to do something or go all out for something, you make the greatest possible effort to do it or get it.","ex":{"en":"They will go all out to get exactly what they want","cn":"他们将尽最大努力实现自己的愿望。"}},{"pos":"PHRASE 短语","cn":"干（或说）什么都行；什么事都不新鲜","en":"If people say 'anything goes', they mean that anything people say or do is considered acceptable, and usually they mean that they do not approve of this.","ex":{"en":"In the 90s, almost anything goes.","cn":"在90年代几乎无奇不有。"}},{"pos":"PHRASE 短语","cn":"与同类的事物相比/跟其他小孩相比","en":"You use expressions like as things go or as children go when you are describing one person or thing and comparing them with others of the same kind.","ex":{"en":"This is a straightforward case, as these things go","cn":"同其他同类情况相比，这件事还算简单。"}},{"pos":"PHRASE 短语","cn":"未事先准备；无意之中","en":"If you do something as you go along, you do it while you are doing another thing, without preparing it beforehand.","ex":{"en":"Learning how to become a parent takes time. It's a skill you learn as you go along.","cn":"学会如何为人父母需要时间，这种技能只能边经历边学习。"}},{"pos":"PHRASE 短语","cn":"干蠢事；犯傻","en":"If you say that someone has gone and done something, you are expressing your annoyance at the foolish thing they have done.","ex":{"en":"Well, he's gone and done it again, hasn't he?","cn":"噢，他又干傻事了，是吧？"}},{"pos":"CONVENTION 惯用语","cn":"大胆尝试吧","en":"You say 'Go for it' to encourage someone to increase their efforts to achieve or win something."},{"pos":"PHRASE 短语","cn":"攻击；批评；非难","en":"If someone has a go at you, they criticize you, often in a way that you feel is unfair.","ex":{"en":"Some people had a go at us for it, which made us more angry.","cn":"一些人因为此事攻击我们，这使我们更加气愤。"}},{"pos":"CONVENTION 惯用语","cn":"我们下一步该怎么办","en":"If someone says 'Where do we go from here?' they are asking what should be done next, usually because a problem has not been solved in a satisfactory way."},{"pos":"PHRASE 短语","cn":"在…方面取得一定成功","en":"If you say that someone is making a go of something such as a business or relationship, you mean that they are having some success with it.","ex":{"en":"I knew we could make a go of it and be happy.","cn":"我知道我们能做成这件事并且会很开心。"}},{"pos":"PHRASE 短语","cn":"忙个没完；十分活跃","en":"If you say that someone is always on the go, you mean that they are always busy and active.","ex":{"en":"I got a new job this year where I am on the go all the time.","cn":"我今年找了份新工作，一直忙得不可开交。"}},{"pos":"PHRASE 短语","cn":"忙于做…","en":"If you have something on the go, you have started it and are busy doing it.","ex":{"en":"Do you like to have many projects on the go at any one time?","cn":"你喜欢一次忙多个项目吗？"}},{"pos":"PHRASE 短语","cn":"待做；有待完成","en":"If you say that there are a particular number of things to go, you mean that they still remain to be dealt with.","ex":{"en":"I still had another five operations to go.","cn":"我还有5例手术要做。"}},{"pos":"PHRASE 短语","cn":"（时间）剩下","en":"If you say that there is a certain amount of time to go, you mean that there is that amount of time left before something happens or ends.","ex":{"en":"There is a week to go until the elections.","cn":"离选举还有一周的时间。"}},{"pos":"PHRASE 短语","cn":"（食物）带出餐馆吃的，外卖的","en":"If you are in a café or restaurant and ask for an item of food to go, you mean that you want to take it away with you and not eat it there.","ex":{"en":"Large fries to go.","cn":"大份炸薯条带走。"}},{"pos":"","cn":"","en":"相关词组：go about go after go against go ahead go along go along with go around go around with go at go away go back go back on go back to go before go by go down go down as go down on go down with go for go in go in for go into go off go off with go on go out go out for go out of go over go over to go round go through go through with go towards go under go up go with go without"}]},"examples":[{"en":"I asked ‘How much?’ and he goes, ‘Fifty’ and I go, ‘Fifty? You must be joking!’","cn":"我问：“多少钱？”他回答说：“五十。”我又说：“五十？你是在开玩笑吧！”"},{"en":"He's offered £3 000 for the car and I don't think he'll go any higher.","cn":"他出价 3 000 英镑买这辆汽车，我看他不会愿意再多付了。"}]},"goal":{"media":{"img":["media/pic/sports_comp.jpg","media/thumb/soccer.jpg"],"uk":"media/uk/goal__gb_1.mp3","us":"media/us/goal__us_1.mp3"},"oxford":{"phon":"ɡəʊl","pos":"noun","senses":[{"en":"a frame with a net into which players must kick or hit the ball in order to score a point","cn":"球门","ex":{"en":"He headed the ball into an open goal (= one that had nobody defending it).","cn":"他把球顶进了空门。"}},{"en":"the act of kicking or hitting the ball into the goal; a point that is scored for this","cn":"射门；进球得分","ex":{"en":"She scored twenty goals in her first season.","cn":"她在第一个赛季进了二十个球。"}},{"en":"something that you hope to achieve","cn":"目标；目的","ex":{"en":"to achieve/accomplish/reach a goal","cn":"达到目标"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（足球、无板篮球或曲棍球等的）球门","en":"In games such as football, netball or hockey, the goal is the space into which the players try to get the ball in order to score a point for their team.","ex":{"en":"David Seaman was back in the Arsenal goal after breaking a knuckle.","cn":"戴维·西曼在一个指关节骨折后又回到阿森纳队的球门前。"}},{"pos":"N-COUNT 可数名词","cn":"（足球或曲棍球赛等的）进球，进球得分","en":"In games such as football or hockey, a goal is when a player gets the ball into the goal, or the point that is scored by doing this.","ex":{"en":"They scored five goals in the first half of the match","cn":"他们在上半场比赛中攻入了5球。"}},{"pos":"N-COUNT 可数名词","cn":"目标；目的","en":"Something that is your goal is something that you hope to achieve, especially when much time and effort will be needed.","ex":{"en":"It's a matter of setting your own goals and following them.","cn":"这就需要设立自己的目标并为之努力。"}}]},"examples":[{"en":"Our ultimate goal must be the preservation of the environment.","cn":"我们的最终目的必须是环境保护。"},{"en":"United conceded two goals in the first half.","cn":"联队在上半场被攻入了两球。"}]},"goods":{"media":{"uk":"media/uk/goods__gb_1.mp3","us":"media/us/goods__us_1.mp3"},"oxford":{"phon":"ɡʊdz","pos":"noun","senses":[{"en":"things that are produced to be sold","cn":"商品；货品","ex":{"en":"to produce/buy/sell goods","cn":"生产／购买／销售商品"}},{"en":"possessions that can be moved","cn":"动产；私人财产","ex":{"en":"He was accused of handling stolen goods.","cn":"他被指控买卖赃物。"}},{"en":"things (not people) that are transported by railway or road","cn":"（铁路或公路）运载的货物","lab":"British English","ex":{"en":"A goods train was derailed last night.","cn":"昨晚一列货车脱轨。"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"货物；商品","en":"Goods are things that are made to be sold.","ex":{"en":"Money can be exchanged for goods or services.","cn":"钱可以用来换取商品或服务。"}},{"pos":"N-PLURAL 复数名词","cn":"私人财产；动产","en":"Your goods are the things that you own and that can be moved.","ex":{"en":"All his worldly goods were packed into a neat checked carrier bag","cn":"他的所有家当都装在一个干净的方格图案手提袋里。"}},{"pos":"PHRASE 短语","cn":"不负众望；达到要求","en":"If you deliver the goods or come up with the goods, you do what is expected or required of you.","ex":{"en":"As long as I deliver the goods, my boss is very happy.","cn":"只要我做好本职工作，我的老板就很高兴。"}},{"pos":"PHRASE 短语","cn":"掌握了…的罪证（或把柄）","en":"If you get the goods or have the goods on someone, you have evidence that they have done something wrong or criminal.","ex":{"en":"He was the victim of those in his own party who had the goods on him.","cn":"党内一些人掌握了他的把柄，结果他成了牺牲品。"}}]},"examples":[{"en":"We expected great things of the England team, but on the day they simply failed to deliver the goods.","cn":"我们本指望英格兰队大获全胜，可那天他们真是有负众望。"},{"en":"The plastic bag contained all his worldly goods (= everything he owned).","cn":"这塑料袋里装着他的全部家当。"}],"base":"good"},"golf":{"oxford":{"phon":"ɡɒlf","pos":"noun","senses":[{"en":"a game played over a large area of ground using sticks with a special shape to hit a small hard ball (a golf ball) into a series of 9 or 18 holes, using as few shots as possible","cn":"高尔夫球运动","ex":{"en":"I play golf every weekend.","cn":"我每个周末都打高尔夫球。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"高尔夫球运动","en":"Golf is a game in which you use long sticks called clubs to hit a small, hard ball into holes that are spread out over a large area of grassy land."}]},"media":{"img":["media/pic/hobbies_comp.jpg","media/thumb/golf.jpg"],"uk":"media/uk/golf__gb_1.mp3","us":"media/us/golf__us_1.mp3"},"examples":[{"en":"He enjoyed a round of golf on a Sunday morning.","cn":"他喜欢星期天的上午打一场高尔夫球。"},{"en":"He plays golf on Sundays.","cn":"他星期天都去打高尔夫球。"}]},"gods":{"lemma":"god","media":{"uk":"media/uk/god__gb_1.mp3","us":"media/us/god__us_1.mp3"}},"gorilla":{"media":{"uk":"media/uk/gorilla__gb_1.mp3","us":"media/us/gorilla__us_1.mp3"},"oxford":{"phon":"ɡəˈrɪlə","pos":"noun","senses":[{"en":"a very large powerful African ape (= an animal like a large monkey without a tail) covered with black or brown hair","cn":"大猩猩（产于非洲）"},{"en":"a large aggressive man","cn":"高大凶恶的人","lab":"informal"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大猩猩","en":"A gorilla is a very large ape. It has long arms, black fur, and a black face."}]}},"goodwill":{"media":{"uk":"media/uk/goodwill__gb_1.mp3","us":"media/us/goodwill__us_1.mp3"},"oxford":{"phon":"ˌɡʊdˈwɪl","pos":"noun","senses":[{"en":"friendly or helpful feelings towards other people or countries","cn":"友善；友好；善意；亲善","ex":{"en":"a spirit of goodwill in international relations","cn":"国际关系中的亲善精神"}},{"en":"the good relationship between a business and its customers that is calculated as part of its value when it is sold","cn":"信誉；商誉"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"友善；善意；亲善","en":"Goodwill is a friendly or helpful attitude towards other people, countries, or organizations.","ex":{"en":"I invited them to dinner, a gesture of goodwill","cn":"我请他们吃饭以示友善。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"信誉；商誉","en":"The goodwill of a business is something such as its good reputation, which increases the value of the business.","ex":{"en":"We do not want to lose the goodwill built up over 175 years.","cn":"我们不想让历经175年树立起来的良好信誉毁于一旦。"}}]},"examples":[{"en":"a spirit of goodwill in international relations","cn":"国际关系中的亲善精神"},{"en":"a goodwill gesture/a gesture of goodwill","cn":"友好的表示"}]},"goat":{"media":{"uk":"media/uk/goat__gb_1.mp3","us":"media/us/goat__us_1.mp3","img":["media/ldoce/img/goat.jpg"]},"oxford":{"phon":"ɡəʊt","pos":"noun","senses":[{"en":"an animal with horns and a coat of hair, that lives wild in mountain areas or is kept on farms for its milk or meat","cn":"山羊","ex":{"en":"a mountain goat","cn":"山羊"}},{"en":"an old man who you think is unpleasant and annoying in a sexual way","cn":"老色鬼；色狼；好色之徒","lab":"informal"},{"en":"the best person ever in a particular field, especially a sport (the abbreviation for greatest of all time)","cn":"史上最佳，史上最伟大（Greatest Of All Time 的缩写）","ex":{"en":"There's no doubt he's the GOAT, but someone's going to beat him one day.","cn":"毫无疑问，他是山羊，但总有一天有人会打败他。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"山羊","en":"A goat is a farm animal or a wild animal that is about the size of a sheep. Goats have horns, and hairs on their chin which resemble a beard."}]},"examples":[{"en":"goat's milk/cheese","cn":"羊奶；羊奶酪"},{"en":"a mountain goat","cn":"山羊"}]},"government":{"media":{"uk":"media/uk/government__gb_1.mp3","us":"media/us/government__us_1.mp3"},"oxford":{"phon":"ˈɡʌvənmənt","pos":"noun","senses":[{"en":"the group of people who are responsible for controlling a country or a state","cn":"政府；内阁","g":"[countable + singular or plural verb]","lab":"especially North American English","ex":{"en":"to lead/form a government","cn":"领导政府；组成内阁"}},{"en":"a particular system or method of controlling a country","cn":"政体；国家体制","g":"[uncountable]","ex":{"en":"Democratic government has now replaced military rule.","cn":"民主政体现已取代军事统治。"}},{"en":"the activity or the manner of controlling a country","cn":"（一国的）统治，治理，统治方式，管理方式","g":"[uncountable]","ex":{"en":"We need strong government to take the country through this crisis.","cn":"我们需要靠强有力的政府管理使国家渡过这次危机。"}}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"政府;内阁","en":"The government of a country is the group of people who are responsible for governing it.","ex":{"en":"The Government has insisted that confidence is needed before the economy can improve.","cn":"政府坚持认为只有坚定信心经济才会有起色。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(国家等的)治理，管理，执政","en":"Government consists of the activities, methods, and principles involved in governing a country or other political unit.","ex":{"en":"The first four years of government were completely disastrous.","cn":"政府前4年的执政彻底失败。"}}]},"examples":[{"en":"Foreign governments have been consulted about this decision.","cn":"这一决定曾征求过他国政府的意见。"},{"en":"The Government has/have been considering further tax cuts.","cn":"政府一直在考虑进一步减税的问题。"}]},"going":{"media":{"uk":"media/uk/going__gb_1.mp3","us":"media/us/going__us_1.mp3"},"oxford":{"phon":"ˈɡəʊɪŋ","pos":"noun","senses":[{"en":"an act of leaving a place","cn":"离去；去；离开","g":"[singular]","lab":"formal","ex":{"en":"We were all sad at her going.","cn":"我们对她的离去都很难过。"}},{"en":"the speed with which somebody does something; how difficult it is to do something","cn":"进展速度；难度","g":"[uncountable]","ex":{"en":"Walking four miles in an hour is pretty good going for me.","cn":"一小时走四英里对我来说是相当不错了。"}},{"en":"the condition of the ground, especially in horse racing","cn":"（尤指赛马场的）地面状况","g":"[uncountable]","ex":{"en":"The going is good to firm.","cn":"赛马场的地面稍偏硬。"}},{"en":"going regularly to the place or event mentioned","cn":"常去…的","ex":{"en":"the theatre-going public","cn":"常去戏院的观众"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"PHR-MODAL 情态动词短语","cn":"将要，即将（发生）","en":"If you say that something is going to happen, you mean that it will happen in the future, usually quite soon.","ex":{"en":"I think it's going to be successful","cn":"我认为这事会成功。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"想要（做…）；决定（做…）","en":"You say that you are going to do something to express your intention or determination to do it.","ex":{"en":"I'm going to go to bed","cn":"我要睡觉了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"进展（或进行）情况","en":"You use the going to talk about how easy or difficult it is to do something. You can also say that something is, for example, hard going or tough going .","ex":{"en":"He has her support to fall back on when the going gets tough","cn":"他在进展困难的时候可以求助于她。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（赛马场等的）地面状况","en":"In horse racing and horse riding, when you talk about the going, you are talking about the condition of the surface the horses are running on.","ex":{"en":"The going was soft; some horses found it hard work.","cn":"这块场地偏软，有一些马跑得很费劲。"}},{"pos":"ADJ 形容词","cn":"（价格、工资等）通常的，现行的","en":"The going rate or the going salary is the usual amount of money that you expect to pay or receive for something.","ex":{"en":"She says that's the going rate for a house this big","cn":"她说这么大的房子现在就是这个价。"}},{"pos":"PHRASE 短语","cn":"占优势；占有利条件","en":"If someone or something has a lot going for them, they have a lot of advantages.","ex":{"en":"This area has a lot going for it","cn":"该地区占据很多优势。"}},{"pos":"PHRASE 短语","cn":"（尤指耽搁后）开始做，出发","en":"When you get going, you start doing something or start a journey, especially after a delay.","ex":{"en":"Now what about that shopping list? I've got to get going.","cn":"那张购物清单呢？我得出发了。"}},{"pos":"PHRASE 短语","cn":"趁情况还有利时","en":"If you say that someone should do something while the going is good, you are advising them to do it while things are going well and they still have the opportunity, because you think it will become much more difficult to do.","ex":{"en":"People are leaving in their thousands while the going is good.","cn":"成千上万的人趁着局势稳定赶紧撤离。"}},{"pos":"PHRASE 短语","cn":"继续做","en":"If you keep going, you continue doing things or doing a particular thing.","ex":{"en":"I like to keep going. I hate to sit still.","cn":"我喜欢一直有事情做，讨厌一动不动地坐着。"}},{"pos":"PHRASE 短语","cn":"维持下去","en":"If you can keep going with the money you have, you can manage to live on it.","ex":{"en":"Things were difficult, and we needed her wages to keep going.","cn":"日子很艰难，我们要靠她的工资来维持生活。"}},{"pos":"PHRASE 短语","cn":"进展顺利；进展不错","en":"If you say that something that has been achieved is good going or not bad going, you mean that it is better than usual or than expected.","ex":{"en":"4,000 copies of Wuthering Heights went in two days. That's not bad going for a book that has been on the market for 145 years.","cn":"4,000册《呼啸山庄》在两天内销售一空，对于一本已经面市145年的书而言，这是一个不错的成绩。"}},{"pos":"PHRASE 短语","cn":"眼下；暂时","en":"If you say that something is enough to be going on with, you mean that it is enough for your needs at the moment, although you will need something better at some time in the future.","ex":{"en":"It was a good enough description for Mattie to be going on with.","cn":"这个描述对玛蒂来说暂时还不错。"}},{"pos":"PHRASE 短语","cn":"接近；快；几乎","en":"You can use going on before a number to say that something has almost reached that number. For example, you can say that someone is going on 40 to indicate that they are nearly 40.","ex":{"en":"We've been married for going on two years","cn":"我们结婚快两年了。"}},{"pos":"See also:","cn":"","en":"going concern→see: ;"}]},"examples":[{"en":"She had her own company by 25 — not bad going!","cn":"她 25 岁时就有了自己的公司，真了不起！"},{"en":"Walking four miles in an hour is pretty good going for me.","cn":"一小时走四英里对我来说是相当不错了。"}],"base":"go"},"gothic":{"media":{"uk":"media/uk/gothic__gb_1.mp3","us":"media/us/gothic__us_1.mp3"},"oxford":{"phon":"ˈɡɒθɪk","pos":"adjective","senses":[{"en":"connected with the Goths (= a Germanic people who fought against the Roman Empire)","cn":"哥特人的，哥特族的，哥特语的"},{"en":"built in the style that was popular in western Europe from the 12th to the 16th centuries, and which has pointed arches and windows and tall thin pillars","cn":"哥特式的，哥特风格的（12 至 16 世纪流行于西欧的建筑风格，以尖拱、尖窗和细长柱为特色）","lab":"architecture","ex":{"en":"a Gothic church","cn":"哥特式教堂"}},{"en":"written in the style popular in the 18th and 19th centuries, which described romantic adventures in mysterious or frightening places or situations","cn":"哥特派的，哥特风格的（流行于 18 至 19 世纪，描述神秘或恐怖背景下的浪漫历险故事）"},{"en":"having pointed letters with thick lines and sharp angles. German books used to be printed in this style.","cn":"哥特体黑体字的（旧时德语书籍常用）"},{"en":"connected with goths","cn":"哥特派的"},{"en":"the Gothic style of architecture","cn":"哥特式建筑；尖拱式建筑","pos":"noun"},{"en":"Gothic printing type or printed letters","cn":"哥特体黑体字","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（建筑等）哥特式的，哥特风格的","en":"Gothic architecture and religious art was produced in the Middle Ages. Its features include tall pillars, high curved ceilings, and pointed arches.","ex":{"en":"...a vast, lofty Gothic cathedral.","cn":"宏伟高耸的哥特式教堂"}},{"pos":"ADJ 形容词","cn":"（小说）哥特派的（描写怪诞、神秘的恐怖故事）","en":"In Gothic stories, strange, mysterious adventures happen in dark and lonely places such as graveyards and old castles.","ex":{"en":"This novel is not science fiction, nor is it Gothic horror.","cn":"这本小说既非科幻小说亦非哥特派恐怖小说。"}},{"pos":"ADJ 形容词","cn":"（印刷或书写文字）哥特体的，花体的，德文老式字体的","en":"Gothic is used to describe a style of printing or writing in which the letters are very decorative. German books and signs were often written in Gothic script."}]},"examples":[{"en":"a Gothic church","cn":"哥特式教堂"}]},"gotten":{"lemma":"get","media":{"uk":"media/uk/gotten__gb_1.mp3","us":"media/us/gotten__us_1.mp3"}},"good-natured":{"oxford":{"phon":"ˌɡʊd ˈneɪtʃəd","pos":"adjective","senses":[{"en":"kind, friendly and patient when dealing with people","cn":"本性善良的；和蔼可亲的；友好的","ex":{"en":"a good-natured person/discussion","cn":"和蔼可亲的人；友好的讨论"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"性情温和的；友善的；温驯的","en":"A good-natured person or animal is naturally friendly and does not get angry easily.","ex":{"en":"Bates looks like a good-natured lad","cn":"贝茨看起来像个性情温和的小伙子。"}}]},"media":{"uk":"media/uk/good_natured_1_gb_1.mp3","us":"media/us/good_natured_1_us_1.mp3"},"examples":[{"en":"a good-natured person/discussion","cn":"和蔼可亲的人；友好的讨论"},{"en":"to smile good-naturedly","cn":"和善地微笑"}]},"gorgeous":{"media":{"uk":"media/uk/gorgeous__gb_1.mp3","us":"media/us/gorgeous__us_1.mp3"},"oxford":{"phon":"ˈɡɔːdʒəs","pos":"adjective","senses":[{"en":"very beautiful and attractive; giving great pleasure","cn":"非常漂亮的；美丽动人的；令人愉快的","lab":"informal","ex":{"en":"a gorgeous girl/man","cn":"漂亮的女郎；美男子"}},{"en":"with very deep colours; impressive","cn":"绚丽的；灿烂的；华丽的","g":"[usually before noun]","ex":{"en":"exotic birds with feathers of gorgeous colours","cn":"长着绚丽羽毛的异国的鸟"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人愉快的；美丽动人的；引人入胜的","en":"If you say that something is gorgeous, you mean that it gives you a lot of pleasure or is very attractive.","ex":{"en":"...gorgeous mountain scenery","cn":"秀丽的山间景色"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"性感的；漂亮的","en":"If you describe someone as gorgeous, you mean that you find them very sexually attractive.","ex":{"en":"The cosmetics industry uses gorgeous women to sell its skincare products","cn":"化妆品行业常找一些性感美女来推销护肤产品。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"绚丽的；华丽的；灿烂的","en":"If you describe things such as clothes and colours as gorgeous, you mean they are bright, rich, and impressive.","ex":{"en":"...a red-haired man in the gorgeous uniform of a Marshal of the Empire.","cn":"身着华丽的帝国元帅服的红发男子"}}]},"examples":[{"en":"exotic birds with feathers of gorgeous colours","cn":"长着绚丽羽毛的异国的鸟"},{"en":"It was absolutely gorgeous.","cn":"那真是美丽绝伦。"}]},"governing":{"oxford":{"phon":"ˈɡʌvənɪŋ","pos":"adjective","senses":[{"en":"having the right and the authority to control something such as a country or an institution","cn":"统治的；控制的；管理的；治理的","ex":{"en":"The Conservatives were then the governing party.","cn":"那时是保守党当政。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"统治的；管理的；控制的","en":"A governing body or organization is one which controls a particular activity.","ex":{"en":"The league became the governing body for amateur fencing in the U.S.","cn":"该联合会成了美国业余击剑运动的管理机构。"}}]},"media":{"uk":"media/uk/governing__gb_1.mp3","us":"media/us/governing__us_1.mp3"},"examples":[{"en":"The school's governing body (= the group of people who control the organization of the school) took responsibility for the decision.","cn":"学校行政机构对这个决定负责。"},{"en":"The Conservatives were then the governing party.","cn":"那时是保守党当政。"}],"base":"govern"},"got":{"lemma":"get","media":{"uk":"media/uk/got__gb_1.mp3","us":"media/us/got__us_1.mp3"}},"govern":{"oxford":{"phon":"ˈɡʌvn","pos":"verb","senses":[{"en":"to legally control a country or its people and be responsible for introducing new laws, organizing public services, etc.","cn":"统治；控制；管理；治理","g":"[transitive, intransitive]","ex":{"en":"The country is governed by elected representatives of the people.","cn":"这个国家由民选代表统治。"}},{"en":"to control or influence somebody/something or how something happens, functions, etc.","cn":"控制；影响；支配","g":"[transitive, often passive]","ex":{"en":"We need changes in the law governing school attendance.","cn":"我们需要对影响就学率的法规做些改动。"}},{"en":"if a word governs another word or phrase, it affects how that word or phrase is formed or used","cn":"支配（词或短语的形式或用法）","g":"[transitive]","lab":"grammar"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"统治；治理","en":"To govern a place such as a country, or its people, means to be officially in charge of the place, and to have responsibility for making laws, managing the economy, and controlling public services.","ex":{"en":"They go to the polls on Friday to choose the people they want to govern their country","cn":"星期五，他们去投票站投票选择他们所期望的国家管理者。"}},{"pos":"VERB 动词","cn":"支配；控制；影响","en":"If a situation or activity is governed by a particular factor, rule, or force, it is controlled by that factor, rule, or force.","ex":{"en":"Marine insurance is governed by a strict series of rules and regulations","cn":"关于海险有一系列严格的规章制度对其作了规定。"}}]},"media":{"uk":"media/uk/govern__gb_1.mp3","us":"media/us/govern__us_1.mp3"},"examples":[{"en":"We need changes in the law governing school attendance.","cn":"我们需要对影响就学率的法规做些改动。"},{"en":"All his decisions have been entirely governed by self-interest.","cn":"他的所有决定都受利己之心的支配。"}]},"goodbye":{"media":{"uk":"media/uk/goodbye__gb_1.mp3","us":"media/us/goodbye__us_1.mp3"},"oxford":{"phon":"ˌɡʊdˈbaɪ","pos":"exclamation, noun","senses":[{"en":"used when you are leaving somebody or when somebody else is leaving","cn":"再见；再会","lab":"figurative","ex":{"en":"Goodbye! It was great to meet you.","cn":"再见！认识你很高兴。"}}]},"collins":{"senses":[{"pos":"CONVENTION 惯用语","cn":"（告别用语）再见","en":"You say 'Goodbye' to someone when you or they are leaving, or at the end of a telephone conversation."},{"pos":"N-COUNT 可数名词","cn":"告别语；道别；再见","en":"When you say your goodbyes, you say something such as 'Goodbye' when you leave.","ex":{"en":"He said his goodbyes knowing that a long time would pass before he would see his child again","cn":"他道了别，知道要过很久才能再见到他的孩子。"}},{"pos":"PHRASE 短语","cn":"道别/ 挥手告别","en":"When you say goodbye to someone, you say something such as 'Goodbye', 'Bye', or 'See you', when you or they are leaving. You can also wave goodbye to someone.","ex":{"en":"He left without saying goodbye","cn":"他不辞而别。"}},{"pos":"PHRASE 短语","cn":"向…说再见；承认不会（或不再）拥有","en":"If you say goodbye or wave goodbye to something that you want or usually have, you accept that you are not going to have it.","ex":{"en":"He has probably said goodbye to his last chance of Olympic gold","cn":"他可能已经失去了夺取奥运会金牌的最后机会。"}},{"pos":"","cn":"","en":"to kiss something goodbye→see: ;"}]},"examples":[{"en":"( figurative ) Take out our service contract and say goodbye to costly repair bills.","cn":"接受我们的服务合同，告别昂贵的修理费吧。"},{"en":"She didn't even say goodbye to her mother .","cn":"她甚至没有向母亲道个别。"}]},"good":{"media":{"uk":"media/uk/good__gb_1.mp3","us":"media/us/good__us_1.mp3"},"oxford":{"phon":"ɡʊd","pos":"adjective","senses":[{"en":"of high quality or an acceptable standard","cn":"好的；优质的；符合标准的；可接受的","sc":"high quality","ex":{"en":"a good book","cn":"一本好书"}},{"en":"pleasant; that you enjoy or want","cn":"令人愉快的；令人满意的","sc":"pleasant","ex":{"en":"Did you have a good time in London?","cn":"你在伦敦过得愉快吗？"}},{"en":"sensible, logical or strongly supporting what is being discussed","cn":"合情理的；有说服力的；有充分根据的","sc":"sensible/strong","ex":{"en":"Thank you, good question.","cn":"谢谢，问题提得好。"}},{"en":"showing or getting approval or respect","cn":"赞同的；赢得赞许的；令人尊敬的","sc":"favourable","ex":{"en":"The play had good reviews.","cn":"这部戏受到好评。"}},{"en":"able to do something well","cn":"擅长的；精通的","sc":"skilful","ex":{"en":"a good player","cn":"优秀的选手"}},{"en":"able to use something or deal with people well","cn":"灵巧的；精明的；善于应付…的","sc":"skilful","ex":{"en":"She's good with her hands (= able to make things, etc.).","cn":"她手很巧。"}},{"en":"morally right; behaving in a way that is morally right","cn":"符合道德的；正派的；高尚的","sc":"morally right","ex":{"en":"She has tried to lead a good life.","cn":"她努力规规矩矩地生活。"}},{"en":"following strictly a set of rules or principles","cn":"循规蹈矩的；守规矩的","sc":"following rules","ex":{"en":"It is good practice to supply a written report to the buyer.","cn":"向买主提供书面报告是诚信的做法。"}},{"en":"willing to help; kind to other people","cn":"乐于助人的；心地善良的；好心的","sc":"kind","ex":{"en":"You've always been such a good friend.","cn":"你一直都是我的好朋友。"}},{"en":"behaving well or politely","cn":"温顺的；乖的；有礼貌的","sc":"child/animal","ex":{"en":"You can stay up late if you're good.","cn":"你要是听话就可以晚一点睡觉。"}},{"en":"healthy or strong","cn":"健康的；强健的；健壮的","sc":"healthy","ex":{"en":"Can you speak into my good ear?","cn":"对着我这只没毛病的耳朵说好吗？"}},{"en":"having a useful or helpful effect on somebody/something","cn":"（对…）有用，有好处","lab":"informal","sc":"useful/helpful","ex":{"en":"Living so close to a chemicals factory can't be good.","cn":"住得离化工厂这么近可不是什么好事。"}},{"en":"suitable or appropriate","cn":"合适的；适宜的；恰当的；适合…的","sc":"suitable","ex":{"en":"Now is a good time to buy a house.","cn":"现在买房子正是时候。"}},{"en":"used in speaking to show that you approve of or are pleased about something that has been said or done, or to show that you want to move on to a new topic of conversation","cn":"（用于口语，表示赞同、满意或转换话题）","sc":"showing approval","ex":{"en":"‘Dinner's ready.’ ‘Good—I'm starving.’","cn":"“晚饭好了。”“太好了，我正饿得很。”"}},{"en":"used as a form of praise","cn":"（用作赞语）","g":"[only before noun]","lab":"informal","sc":"showing approval","ex":{"en":"Good old Jack!","cn":"好心的杰克！"}},{"en":"used in exclamations","cn":"（用于感叹）","lab":"informal","sc":"in exclamations","ex":{"en":"Good heavens!","cn":"天啊！"}},{"en":"great in number, amount or degree","cn":"（数量或程度）相当大的，相当多的","g":"[only before noun]","sc":"large","ex":{"en":"a good number of people","cn":"相当多的人"}},{"en":"not less than; rather more than","cn":"不少于；稍多于","sc":"at least","ex":{"en":"We waited for a good hour.","cn":"我们等了至少一小时。"}},{"en":"done to a high level or a great degree; complete","cn":"彻底的；完全的","g":"[only before noun]","sc":"complete","ex":{"en":"We had a good laugh about it afterwards.","cn":"我们后来对此笑了个痛快。"}},{"en":"funny or clever","cn":"有趣的；巧妙的","g":"[usually before noun]","lab":"informal","sc":"amusing","ex":{"en":"a good story/joke","cn":"有趣的故事／笑话"}},{"en":"having enough energy, health, strength, etc. to last for a particular length of time or distance","cn":"（精力、健康、力量等）足以维持…的，能持续…的","sc":"for particular time/distance","ex":{"en":"You're good for (= you will live) a few years yet.","cn":"你还可以活上几年。"}},{"en":"acceptable for something","cn":"有效的；可接受的","sc":"for particular time/distance","ex":{"en":"The ticket is good for three months.","cn":"这张票三个月内有效。"}},{"en":"likely to provide something","cn":"能提供…的","sc":"likely to provide","ex":{"en":"He's always good for a laugh.","cn":"他总能逗人发笑。"}},{"en":"behaviour that is morally right or acceptable","cn":"合乎道德的行为；正直的行为；善行","g":"[uncountable]","sc":"morally right","ex":{"en":"Do they even know the difference between good and evil?","cn":"他们到底知不知道善与恶的区别？"},"pos":"noun"},{"en":"people who live a moral life; people who are admired for the work they do to help other people","cn":"有道德的人；高尚的人；好人","g":"[plural]","sc":"morally right","ex":{"en":"a gathering of the great and the good","cn":"群贤荟萃"},"pos":"noun"},{"en":"something that helps somebody/something","cn":"用处；好处；益处","g":"[uncountable]","sc":"something helpful","ex":{"en":"Cuts have been made for the good of the company.","cn":"实行裁减是为了公司的利益。"},"pos":"noun"},{"en":"well","cn":"好","ex":{"en":"‘How's it going?’ ‘Pretty good.’","cn":"“事情进展如何？”“非常好。”"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愉快的；有趣的；令人愉快的","en":"Good means pleasant or enjoyable.","ex":{"en":"We had a really good time together","cn":"我们一起玩得真痛快。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"好的；高品质的；高水准的","en":"Good means of a high quality, standard, or level.","ex":{"en":"Exercise is just as important to health as good food","cn":"锻炼与合理膳食对健康同等重要。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"擅长的；精通的；能干的","en":"If you are good at something, you are skilful and successful at doing it.","ex":{"en":"He was very good at his work","cn":"他工作非常出色。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有利的；有益的","en":"If you describe a piece of news, an action, or an effect as good, you mean that it is likely to result in benefit or success.","ex":{"en":"On balance biotechnology should be good news for developing countries","cn":"总的来说，生物技术对发展中国家应该是有利的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"合情理的；理由充足的；有根据的","en":"A good idea, reason, method, or decision is a sensible or valid one.","ex":{"en":"They thought it was a good idea to make some offenders do community service","cn":"他们认为让一些违法者去社区做义工是个好主意。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人满意的；合适的；正确的","en":"If you say that it is good that something should happen or good to do something, you mean it is desirable, acceptable, or right.","ex":{"en":"I think it's good that some people are going","cn":"我认为一些人要去是好事情。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精确的；准确的","en":"A good estimate or indication of something is an accurate one.","ex":{"en":"We have a fairly good idea of what's going on","cn":"我们对正在发生的事有着相当清楚的认识。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"划算的；收益可观的","en":"If you get a good deal or a good price when you buy or sell something, you receive a lot in exchange for what you give.","ex":{"en":"Whether such properties are a good deal will depend on individual situations","cn":"这样的地产是否可获得大笔收益还要视具体情形而定。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有利的；有益的","en":"If something is good for a person or organization, it benefits them.","ex":{"en":"Rain water was once considered to be good for the complexion","cn":"雨水曾一度被认为可以滋养皮肤。"}},{"pos":"N-SING 单数名词","cn":"好处；利益","en":"If something is done for the good of a person or organization, it is done in order to benefit them.","ex":{"en":"Furlaud urged him to resign for the good of the country","cn":"弗劳德敦促他为了国家的利益辞职。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"差强人意；低劣；不好","en":"If someone or something is no good or is not any good, they are not satisfactory or are of a low standard.","ex":{"en":"If the weather's no good then I won't take any pictures","cn":"如果天气不好，我就不拍照了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"没好处；没用处","en":"If you say that doing something is no good or does not do any good, you mean that doing it is not of any use or will not bring any success.","ex":{"en":"It's no good worrying about it now","cn":"现在就为此发愁根本没用。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"善行；美德；合乎道德的行为","en":"Good is what is considered to be right according to moral standards or religious beliefs.","ex":{"en":"Good and evil may co-exist within one family.","cn":"善与恶可能并存于一体。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"正直的；高尚的；品行好的","en":"Someone who is good is morally correct in their attitudes and behaviour.","ex":{"en":"The president is a good man","cn":"总统是个品行端正的人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指小孩）乖的，恭顺的，有礼貌的","en":"Someone, especially a child, who is good obeys rules and instructions and behaves in a socially correct way.","ex":{"en":"The children were very good","cn":"孩子们非常听话。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"好心的；体贴的","en":"Someone who is good is kind and thoughtful.","ex":{"en":"You are good to me","cn":"你对我很体贴。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（心情）愉快的","en":"Someone who is in a good mood is cheerful and pleasant to be with.","ex":{"en":"People were in a pretty good mood","cn":"人们的心情十分舒畅。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"亲密的；友好的","en":"If people are good friends, they get on well together and are very close.","ex":{"en":"She and Gavin are good friends","cn":"她与加文是好朋友。"}},{"pos":"ADJ 形容词","cn":"（身体部位或器官）健全的，强健的","en":"A person's good eye, arm, or leg is the one that is healthy and strong, if the other one is injured or weak.","ex":{"en":"He turned his good eye on me and laughed.","cn":"他用那只健全的眼睛看着我笑了。"}},{"pos":"ADJ 形容词","cn":"相当的；非常的","en":"You use good to emphasize the great extent or degree of something.","ex":{"en":"We waited a good fifteen minutes","cn":"我们等了足足15分钟。"}},{"pos":"CONVENTION 惯用语","cn":"好；很好","en":"You say 'Good' or 'Very good' to express pleasure, satisfaction, or agreement with something that has been said or done, especially when you are in a position of authority.","ex":{"en":"'Are you all right?' — 'I'm fine.' — 'Good. So am I.'","cn":"“你还好吗？”——“我挺好。”——“那就好。我也还不错。”"}},{"pos":"PHRASE 短语","cn":"几乎；差不多","en":"'As good as' can be used to mean 'almost.'","ex":{"en":"His career is as good as over","cn":"他的事业差不多完蛋了。"}},{"pos":"PHRASE 短语","cn":"为了共同利益","en":"If you do something for the common good, you do it for the benefit or advantage of everyone.","ex":{"en":"...communities working together for the common good","cn":"为共同利益而团结协作的社区"}},{"pos":"PHRASE 短语","cn":"对…有好处（或有帮助）","en":"If you say that something will do someone good, you mean that it will benefit them or improve them.","ex":{"en":"The outing will do me good","cn":"这次远足对我会有所助益。"}},{"pos":"PHRASE 短语","cn":"永远；永久","en":"If something changes or disappears for good, it never changes back or comes back as it was before.","ex":{"en":"The days of big-time racing at Herne Hill had gone for good","cn":"在赫恩山举行盛大赛马会的日子早已一去不复返了。"}},{"pos":"CONVENTION 惯用语","cn":"（称赞某人）真行，真棒","en":"People say 'Good for you' to express approval of your actions.","ex":{"en":"'He has a girl now, who he lives with.' — 'Good for him.'","cn":"“他现在有女朋友了，他们住在一起。”——“他可真行啊。”"}},{"pos":"PHRASE 短语","cn":"善于做；精通于","en":"If someone is good for something, you can rely on them to provide that thing.","ex":{"en":"Joe was always good for a colorful quote","cn":"乔总能绘声绘色地旁征博引。"}},{"pos":"PHRASE 短语","cn":"庆幸的是，幸运的是（英国英语中作 it's a good job, that）","en":"If you say it's a good thing, or in British English it's a good job ,that something is the case, you mean that it is fortunate.","ex":{"en":"It's a good thing you aren't married","cn":"幸好你没有结婚。"}},{"pos":"PHRASE 短语","cn":"修复；恢复；偿付；赔偿","en":"If you make good some damage, a loss, or a debt, you try to repair the damage, replace what has been lost, or repay the debt.","ex":{"en":"It may cost several billion roubles to make good the damage.","cn":"也许要花上几十亿卢布才能赔偿这一损失。"}},{"pos":"PHRASE 短语","cn":"兑现，履行（诺言等）","en":"If someone makes good a threat or promise or makes good on it, they do what they have threatened or promised to do.","ex":{"en":"Certain that he was going to make good his threat to kill her, she lunged for the gun","cn":"他曾威胁要杀了她，而她确定他这次就要向她索命，便冲上前去拿枪。"}},{"pos":"PHRASE 短语","cn":"获得成功；出名；发迹","en":"If someone makes good, they become successful, famous, or rich.","ex":{"en":"Both men are poor boys made good.","cn":"两人都是出身贫穷，最终干出了一番事业。"}},{"pos":"PHRASE 短语","cn":"（尤指在康复或修复后）同以前一样好","en":"If you say that something or someone is as good as new, you mean that they are in a very good condition or state, especially after they have been damaged or ill.","ex":{"en":"I only ever use that on special occasions so it's as good as new","cn":"我只在特别的场合下才使用它，所以它跟新的一样。"}},{"pos":"PHRASE 短语","cn":"（用于人名、地名或事物名前表示喜爱）亲爱的，可爱的","en":"You use good old before the name of a person, place, or thing when you are referring to them in an affectionate way.","ex":{"en":"Good old Harry. Reliable to the end","cn":"亲爱的哈里。永远值得信赖。"}},{"pos":"PHRASE 短语","cn":"优裕的生活；奢华安逸的生活","en":"If you say that someone is living the good life, you mean that they are living in comfort and luxury with few problems or worries."},{"pos":"","cn":"","en":"to be in someone's good books→see: ; good deal→see: ; in good faith→see: ; so far so good→see: ; a good few→see: ; good as gold→see: ; good gracious→see: ; good grief→see: ; good heavens→see: ; for good or ill→see: ; good job→see: ; good lord→see: ; for good measure→see: ; the good old days→see: ; good question→see: ; in good shape→see: ; to stand someone in good stead→see: ; in good time→see: ; too good to be true→see: ; to be as good as one's word→see: ;"}]},"examples":[{"en":"If these measures also reduce unemployment, that is all to the good.","cn":"要是这些措施也能降低失业率，那就不失为好事。"},{"en":"Can we change our meeting? Monday isn't good (= convenient) for me.","cn":"我们把见面时间改改吧，星期一我不方便。"}]},"gonna":{"media":{"uk":"media/uk/gonna__gb_1.mp3","us":"media/us/gonna__us_1.mp3"},"oxford":{"phon":"ˈɡənə","pos":"","senses":[{"en":"a way of saying or writing ‘going to’ in informal speech, when it refers to the future","cn":"即将，将要（非正式用语，即 going to）","ex":{"en":"What's she gonna do now?","cn":"她现在要干什么？"}}]},"collins":{"senses":[{"pos":"","cn":"（用于书面英语中表示going to的非正式发音形式）","en":"Gonna is used in written English to represent the words 'going to' when they are pronounced informally.","ex":{"en":"Then, what am I gonna do?","cn":"那么，我该怎么办呢？"}}]},"examples":[{"en":"What's she gonna do now?","cn":"她现在要干什么？"},{"en":"This isn’t gonna be easy.","cn":"这事不容易。"}]},"goals":{"lemma":"goal"},"gourmets":{"oxford":{"phon":"ˈɡʊəmeɪ","pos":"noun","senses":[{"en":"a person who knows a lot about good food and wines and who enjoys choosing, eating and drinking them","cn":"美食家；讲究饮食的人；美酒美食品尝家"}]}},"gorillas":{"lemma":"gorilla"},"governors":{"lemma":"governor"},"gossips":{"lemma":"gossip"},"goes":{"lemma":"go"},"governments":{"lemma":"government"},"golfer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"打高尔夫球的人；高尔夫球运动员","en":"A golfer is a person who plays golf for pleasure or as a profession."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a game in which the players hit a small white ball into holes in the ground with a set of golf clubs, using as few hits as possible","cn":""}]},"collocations":{"phrases":["ADJ. brilliant, good | experienced | handicap a low handicap golfer | champion, top | keen | amateur, professional | club","GOLFER + VERB play"]},"media":{"uk":"media/ldoce/hwd/bre/b/golf_las2_br.mp3","us":"media/ldoce/hwd/ame/6/golf.mp3"},"examples":[{"en":"He plays golf on Sundays.","cn":""},{"en":"a round of golf (= complete game of golf )","cn":""}],"oxford":{"phon":"ˈɡɒlfə(r)","pos":"noun","senses":[{"en":"a person who plays golf","cn":"高尔夫球运动员","ex":{"en":"a low handicap golfer","cn":"超过标准杆数不多的高尔夫球手"}}]}},"gospel":{"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"福音书（《圣经·新约》中记录耶稣基督生平和教诲的四卷书）","en":"In the New Testament of the Bible, the Gospels are the four books which describe the life and teachings of Jesus Christ.","ex":{"en":"...the parable in St Matthew's Gospel.","cn":"《马太福音》中的寓言故事"}},{"pos":"N-SING 单数名词","cn":"福音（耶稣的启示和教义）","en":"In the Christian religion, the gospel refers to the message and teachings of Jesus Christ, as explained in the New Testament.","ex":{"en":"I didn't shirk my duties. I visited the sick and I preached the gospel.","cn":"我没有逃避职责，我探望病人，也宣讲福音。"}},{"pos":"N-COUNT 可数名词","cn":"教义；信条","en":"You can use gospel to refer to a particular way of thinking that a person or group believes in very strongly and that they try to persuade others to accept.","ex":{"en":"It taught only materialism, the gospel of mammon.","cn":"它只是宣扬金钱至上的物欲主义。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"福音音乐（尤流行于美国南部黑人基督徒中）","en":"Gospel or gospel music is a style of religious music that uses strong rhythms and vocal harmony. It is especially popular among black Christians in the southern United States of America.","ex":{"en":"I had to go to church, so I grew up singing gospel","cn":"我必须去教堂做礼拜，因此我是唱着福音歌长大的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"绝对真理","en":"If you take something as gospel, or as gospel truth, you believe that it is completely true.","ex":{"en":"The results were not to be taken as gospel","cn":"别以为这些结果就一定是正确的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"definitely true, so that no one could argue or disagree about it","cn":""},{"en":"use this to emphasize that something is definitely true","cn":""},{"en":"one of the four books in the Bible about Christ’s life","cn":"福音书〔《圣经》中有关耶稣生平的四福音书之一〕"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Follow advice like gospel and you're following it as though it was the final word or authority on the matter."}]},"collocations":{"phrases":["ADJ. Christian","VERB + GOSPEL bring, preach, proclaim, spread, take She preached the Christian gospel to the poor and destitute. | hear Thousands came to he","GOSPEL + NOUN message, story"]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdegospel.mp3","us":"media/ldoce/hwd/ame/c/gospel1.mp3"},"examples":[{"en":"Don't take his word as gospel.","cn":"别把他的话当作绝对真理。"},{"en":"He preached a gospel of military strength.","cn":"他鼓吹军事实力主义。"}],"oxford":{"phon":"ˈɡɒspl","pos":"noun","senses":[{"en":"one of the four books in the Bible about the life and teaching of Jesus","cn":"福音（《圣经》中关于耶稣生平和教诲的四福音书之一）","g":"[countable]","ex":{"en":"the Gospel according to St John","cn":"约翰福音"}},{"en":"the life and teaching of Jesus as explained in the Bible","cn":"福音（耶稣的事迹和教诲）","g":"[singular]","lab":"North American English","ex":{"en":"preaching/spreading the gospel","cn":"宣讲／传布福音"}},{"en":"a set of ideas that somebody believes in and tries to persuade others to accept","cn":"（个人的）信念，信仰","g":"[countable, usually singular]","ex":{"en":"He preached a gospel of military strength.","cn":"他鼓吹军事实力主义。"}},{"en":"the complete truth","cn":"绝对真理","g":"[uncountable]","lab":"informal","ex":{"en":"Is that gospel?","cn":"那是绝对真理吗？"}},{"en":"a style of religious singing developed by African Americans","cn":"福音音乐（最初在非裔美国人中间传唱的宗教音乐）","g":"[uncountable]","ex":{"en":"a gospel choir","cn":"福音唱诗班"}}]}},"good-looking":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"漂亮的；好看的","en":"Someone who is good-looking has an attractive face. →see usage note at:","ex":{"en":"Cassandra noticed him because he was good-looking.","cn":"卡桑德拉注意到他因为他长得帅气。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a beautiful woman or child has perfect good looks","cn":""},{"en":"a good-looking person looks nice. Good-looking is very common in spoken English","cn":""},{"en":"an attractive person looks nice, especially in a way that makes you feel sexually interested in them","cn":""}]},"collocations":{"phrases":["VERBS be","ADV. extraordinarily, extremely, really, strikingly, terribly, very | not exactly, not particularly She was not exactly good-looking, but de"]},"media":{"uk":"media/ldoce/hwd/bre/7/good_looking0205.mp3","us":"media/ldoce/hwd/ame/1/good-looking.mp3"},"examples":[{"en":"She's strikingly good-looking.","cn":"她非常漂亮。"},{"en":"a good-looking man/couple","cn":"俊美的男子；漂亮的一对"}],"oxford":{"phon":"ˌɡʊd ˈlʊkɪŋ","pos":"adjective","senses":[{"en":"physically attractive","cn":"漂亮的；好看的","ex":{"en":"a good-looking man/couple","cn":"俊美的男子；漂亮的一对"}}]}},"gown":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"女裙；女礼服；女长服","en":"A gown is a dress, usually a long dress, which women wear on formal occasions.","ex":{"en":"The new ball gown was a great success.","cn":"这种新款舞会礼服很畅销。"}},{"pos":"N-COUNT 可数名词","cn":"（律师、学者等在正式场合穿的）礼袍,长袍","en":"A gown is a loose black garment worn on formal occasions by people such as lawyers and academics.","ex":{"en":"...an old headmaster in a flowing black gown.","cn":"身着宽松黑礼袍的老校长"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long dress that a woman wears on formal occasions","cn":"女礼服"},{"en":"a long loose piece of clothing worn for special ceremonies by judges, teachers, lawyers, and members of universities 〔","cn":"法官﹑教师﹑律师﹑大学成员在特殊仪式上穿的〕长袍"},{"en":"a long loose piece of clothing worn in a hospital by someone doing or having an operation","cn":"外科手术服"}]},"collocations":{"phrases":["ADJ. long | flowing She was dressed in a long flowing gown. | ball, bridal, evening, wedding","GOWN + VERB be trimmed with sth She wore a white satin gown trimmed with lace.","PREP. in a/the ~ 2 worn by judges, surgeons, etc.","ADJ. academic | hospital, surgical","PREP. in a/the ~","PHRASES town and gown (= the permanent members of a university town and the members of its university) •"]},"media":{"uk":"media/ldoce/hwd/bre/8/gown0205.mp3","us":"media/ldoce/hwd/ame/3/gown.mp3"},"examples":[{"en":"an evening/wedding gown","cn":"女晚礼服；新娘的结婚礼服"},{"en":"a surgeon's gown","cn":"外科医生穿的罩衣"}],"oxford":{"phon":"ɡaʊn","pos":"noun","senses":[{"en":"a woman’s dress, especially a long one for special occasions","cn":"（尤指特别场合穿的）女裙，女长服，女礼服","ex":{"en":"an evening/a wedding gown","cn":"晚礼服；婚纱"}},{"en":"a long loose piece of clothing that is worn over other clothes by judges and (in the UK) by other lawyers, and by members of universities (at special ceremonies)","cn":"（法官、英国律师、大学师生在特别仪式上穿的）长袍","ex":{"en":"a graduation gown","cn":"毕业礼服"}},{"en":"a piece of clothing worn in a hospital, either by medical staff during surgery or by a patient, especially as protection against infection","cn":"（医护人员或患者穿的，尤指用于感染防护的）罩衣，防护服","ex":{"en":"a surgeon’s gown","cn":"外科手术服"}}]}},"goalkeeper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"守门员","en":"A goalkeeper is the player in a sports team whose job is to guard the goal."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the player in a sports team whose job is to try to stop the ball going into the goal","cn":"守门员"}]},"collocations":{"phrases":["ADJ. brilliant, excellent, good | England, Liverpool, etc. The England goalkeeper played brilliantly. | international | reserve, substitute ","PREP. ~ for He now plays as goalkeeper for Liverpool."]},"media":{"uk":"media/ldoce/hwd/bre/a/goalkeeper_las2_br.mp3","us":"media/ldoce/hwd/ame/c/goalkeeper.mp3"},"examples":[{"en":"goalkeeping techniques","cn":"守门的技巧"}],"oxford":{"phon":"ˈɡəʊlkiːpə(r)","pos":"noun","senses":[{"en":"a player whose job is to stop the ball from going into his or her own team’s goal","cn":"守门员","ex":{"en":"He now plays as goalkeeper for Liverpool.","cn":"目前他在利物浦队担任守门员。"}}]}}});
